const input=$json.body??$json;
const cal=input.calibration??{};
const blockers=Array.isArray(input.blockers)?input.blockers:[];
const asking=Number(input.asking_price??input.askingPrice);
const mao=Number(cal.adjusted_mao??input.adjusted_mao??input.dynamic_mao);
const projectedProfit=Number(input.projected_assignment_profit??input.projected_profit);
const motivation=String(input.motivation||input.seller_motivation||"unknown").toLowerCase();
const evidenceComplete=input.evidence_complete===true||input.evidence_status==="complete";
const assetType=String(input.asset_type||input.property_type||"residential").toLowerCase();
const identityComplete=Boolean(input.deal_id&&input.lead_id&&input.property_id);
const validEconomics=Number.isFinite(asking)&&Number.isFinite(mao)&&Number.isFinite(projectedProfit);
let decision="needs_evidence",reason="insufficient underwriting evidence";
if(!identityComplete){decision="blocked";reason="missing deal/lead/property identity";}
else if(blockers.length){decision="blocked";reason="active blockers present";}
else if(!validEconomics){decision="needs_evidence";reason="asking price, dynamic MAO, or projected profit is missing/invalid";}
else if(!evidenceComplete){decision="needs_evidence";reason="underwriting evidence is incomplete";}
else if(asking<=mao && projectedProfit>0){decision="pursue";reason="asking price is within dynamic MAO and projected profit is positive";}
else if(asking>mao && asking<=mao*1.10 && projectedProfit>0){decision="negotiate";reason="asking price is above MAO but within a controlled negotiation band";}
else if(asking>mao){decision="pass";reason="asking price exceeds protected dynamic MAO";}
else if(projectedProfit<=0){decision="pass";reason="projected profit is non-positive";}
const strategy={asset_type:assetType,asking_price:asking,dynamic_mao:mao,projected_assignment_profit:projectedProfit,motivation,evidence_complete:evidenceComplete,decision,reason,mao_guardrail:"Do not approve an acquisition price above dynamic MAO without an explicit recalibration/review event.",secondary_rule_note:"70% rule remains secondary/reference only; property economics and executable exit determine the decision."};
let status=decision==="blocked"?"acquisition_blocked":decision==="needs_evidence"?"underwriting_evidence_required":"acquisition_decision_ready";
let nextWorkflow=decision==="pursue"||decision==="negotiate"?"WF-288":decision==="pass"?"WF-289":"WF-126";
const humanReview=decision!=="pursue";
return [{json:{...input,workflow:"WF-287",workflow_name:"Dynamic MAO Calibration → Property-Level Offer Strategy & Acquisition Decision Controller",status,acquisition_strategy:strategy,next_workflow:nextWorkflow,human_review_required:humanReview,audit:{event_type:"property_offer_strategy_acquisition_decision",idempotency_key:input.idempotency_key||`wf-287:${input.deal_id||"unknown"}:${input.property_id||"none"}:${input.version||1}`}}}];
